"""Showcase behavior checks using the real native browser; no external transactions."""
import asyncio,json,sys
from pathlib import Path
from playwright.async_api import async_playwright
async def main():
 base=sys.argv[1] if len(sys.argv)>1 else 'http://127.0.0.1:8845';out=Path(__file__).resolve().parents[1]/'artifacts';checks=[]
 async with async_playwright() as p:
  browser=await p.chromium.launch();context=await browser.new_context(viewport={'width':1440,'height':1100},permissions=['clipboard-read','clipboard-write']);page=await context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  await page.goto(base,wait_until='networkidle')
  async def select(name):await page.locator('nav').get_by_role('button',name=name).click()
  assert await page.locator('nav button').count()==19
  await page.get_by_role('button',name='Next page',exact=True).click();h=page.get_by_role('heading',name='Make the next step visible.');assert await h.evaluate('(x)=>x===document.activeElement');await h.press('End');assert await page.get_by_role('button',name='Next page',exact=True).is_disabled();await page.keyboard.press('Home');assert await page.get_by_role('button',name='Previous page',exact=True).is_disabled();await page.keyboard.press('ArrowRight');assert await page.get_by_role('heading',name='Make the next step visible.').is_visible();await page.wait_for_timeout(450);await page.screenshot(path=str(out/'clearvue-book.png'),full_page=True);checks.append('Book: controlled page changes, title focus, arrow/Home/End and edge buttons')
  await select('Receipt');assert await page.get_by_text('Fictional sample · no payment made').is_visible();assert await page.locator('.cv-receipt-total').inner_text()=='Total\n$128.00'
  async with page.expect_download() as info:await page.get_by_role('button',name='Download receipt').click()
  download=await info.value;path=await download.path();content=Path(path).read_text();assert 'FICTIONAL SAMPLE' in content and 'Total: $128.00' in content
  await page.get_by_role('button',name='Copy receipt').click();await page.get_by_text('Receipt copied.').wait_for();assert await page.evaluate('navigator.clipboard.readText()')==content
  await page.evaluate('()=>{window.__printCalls=0;window.print=()=>window.__printCalls++;}');await page.get_by_role('button',name='Print receipt').click();assert await page.evaluate('window.__printCalls')==1
  await page.screenshot(path=str(out/'clearvue-receipt.png'),full_page=True);checks.append('Receipt: fictional label, cents total, actual download and clipboard, print invocation')
  await select('Payment states');await page.get_by_role('radio',name='failure',exact=True).check();await page.get_by_role('button',name='Retry payment').click();assert await page.get_by_role('heading',name='Waiting for confirmation').is_visible();assert await page.get_by_text('Retry event received locally. No payment was sent.').is_visible();await page.get_by_role('radio',name='success',exact=True).check();await page.get_by_role('button',name='Done',exact=True).click();assert await page.get_by_text('Done event received locally.').is_visible();await page.screenshot(path=str(out/'clearvue-payment.png'),full_page=True);checks.append('Payment states: success/pending/failure rendering and parent retry/done events')
  await select('Pointer companion');pet=page.locator('.cv-pet');await page.mouse.move(350,250);await page.wait_for_timeout(180);first=await pet.evaluate('(x)=>x.style.transform');await page.mouse.move(800,420);await page.wait_for_timeout(180);assert await pet.evaluate('(x)=>x.style.transform')!=first;await page.get_by_role('button',name='Pause companion').click();assert 'following' not in (await pet.get_attribute('class'));await page.get_by_role('button',name='Resume companion').click();await page.emulate_media(reduced_motion='reduce');await page.wait_for_function("document.querySelector('.cv-mascot button').disabled");assert await page.get_by_role('button',name='Pause companion').is_disabled();assert 'following' not in (await pet.get_attribute('class'));await page.screenshot(path=str(out/'clearvue-mascot.png'),full_page=True);await page.emulate_media(reduced_motion='no-preference');checks.append('Mascot: pointer transform updates, pause/resume, reduced-motion stationary mode')
  await select('Chart studio')
  for chart in ['line','area','bar','donut','radar','heatmap']:
   await page.get_by_role('radio',name=chart,exact=True).check();await page.wait_for_timeout(420);assert await page.locator('.cv-chart-canvas svg').count()==1,chart;assert await page.locator('.cv-chart-canvas').evaluate('(x)=>x.clientWidth>0');await page.locator('.cv-data-strip button').first.focus();assert ':' in await page.locator('.cv-chart-readout').inner_text();await page.get_by_text('View data table',exact=True).click();assert await page.get_by_role('table').is_visible();assert await page.locator('tbody tr').count()>0;await page.get_by_text('View data table',exact=True).click();await page.locator('.workspace').screenshot(path=str(out/f'clearvue-chart-{chart}.png'))
  checks.append('Charts: all six SVG types render, keyboard value inspection and populated tables')
  await page.get_by_role('button',name='Dark mode',exact=True).click();await page.screenshot(path=str(out/'clearvue-chart-dark.png'),full_page=True);await page.get_by_role('button',name='Light mode',exact=True).click()
  await select('AI chat UI');entry=page.get_by_role('textbox',name='Your message');await entry.fill('<img src=x onerror=alert(1)>');await entry.press('Enter');await page.get_by_text('Preparing a response.',exact=True).wait_for();await page.get_by_text('Response streaming.',exact=True).wait_for();await page.get_by_text('Response ready.',exact=True).wait_for();assert await page.locator('.cv-chat-message--user img').count()==0;assert await page.locator('.cv-chat .cv-chart-canvas svg').count()==1;assert await page.locator('.cv-chat-citations a').count()==2
  await page.get_by_label('Simulate next response failing').check();await entry.fill('Please retry this sample');await page.get_by_role('button',name='Send message',exact=True).click();await page.get_by_role('button',name='Retry response').wait_for();await page.get_by_role('button',name='Retry response').click();await page.get_by_text('Response ready.',exact=True).wait_for();await entry.fill('Stop this response');await entry.press('Enter');await page.get_by_role('button',name='Stop response').click();assert await page.get_by_role('button',name='Send message',exact=True).is_visible();await page.screenshot(path=str(out/'clearvue-chat.png'),full_page=True);checks.append('Chat: scripted loading/streaming, chart+citation messages, HTML escaping, error/retry, stop')
  await page.set_viewport_size({'width':390,'height':844})
  for name in ['Book flip','Receipt','Payment states','Pointer companion','AI chat UI','Chart studio']:
   await select(name);assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth'),name
   if name=='Chart studio':
    for kind in ['line','area','bar','donut','radar','heatmap']:
     await page.get_by_role('radio',name=kind,exact=True).check();assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth'),kind
   await page.screenshot(path=str(out/('clearvue-'+name.lower().replace(' ','-')+'-mobile.png')),full_page=True)
  checks.append('Mobile: all six showcase surfaces and every chart type fit390px')
  await page.emulate_media(reduced_motion='reduce');await select('Book flip');assert await page.locator('.cv-book-page').evaluate('(x)=>getComputedStyle(x).animationName')=='none';await select('Payment states');await page.get_by_role('radio',name='pending',exact=True).check();assert await page.locator('.cv-payment-orbit').evaluate('(x)=>getComputedStyle(x,"::after").animationName')=='none';checks.append('Reduced motion: book and pending-payment animation disabled')
  touch=await browser.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);tp=await touch.new_page();await tp.goto(base,wait_until='networkidle');await tp.locator('nav').get_by_role('button',name='Pointer companion').click();assert await tp.get_by_role('button',name='Pause companion').is_disabled();assert 'following' not in await tp.locator('.cv-pet').get_attribute('class');await touch.close();checks.append('Coarse pointer: companion stays stationary without needing a mouse')
  assert not errors,errors;(out/'showcase-checks.json').write_text(json.dumps({'base_url':base,'checks':checks,'runtime_errors':errors},indent=2));print(json.dumps({'passed':len(checks),'checks':checks},indent=2));await browser.close()
asyncio.run(main())
